import{_ as e,c as t,o as r,a0 as o}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Mental Game Quick Reference","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/en/summary-sheet.md","filePath":"public/downloads/en/summary-sheet.md"}');const n=e({name:"public/downloads/en/summary-sheet.md"},[["render",function(e,a,n,s,i,l){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="mental-game-quick-reference" tabindex="-1">Mental Game Quick Reference <a class="header-anchor" href="#mental-game-quick-reference" aria-label="Permalink to &quot;Mental Game Quick Reference&quot;">​</a></h1><p><strong>Pétanque Academy - One-Page Summary</strong></p><hr><h2 id="the-zone-flow-state" tabindex="-1">The Zone / Flow State <a class="header-anchor" href="#the-zone-flow-state" aria-label="Permalink to &quot;The Zone / Flow State&quot;">​</a></h2><p><strong>Two Modes of Mind:</strong></p><table tabindex="0"><thead><tr><th>Planning Mode</th><th>Execution Mode</th></tr></thead><tbody><tr><td>Analyze terrain</td><td>Trust your body</td></tr><tr><td>Choose strategy</td><td>Don&#39;t think</td></tr><tr><td>Assess risks</td><td>Present moment</td></tr><tr><td>Make decisions</td><td>Automatic execution</td></tr></tbody></table><p><strong>The Switch:</strong> Plan before, flow during</p><hr><h2 id="inner-critic-vs-inner-coach" tabindex="-1">Inner Critic vs Inner Coach <a class="header-anchor" href="#inner-critic-vs-inner-coach" aria-label="Permalink to &quot;Inner Critic vs Inner Coach&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Inner Critic ❌</th><th>Inner Coach ✅</th></tr></thead><tbody><tr><td>&quot;That was terrible!&quot;</td><td>&quot;What can I learn?&quot;</td></tr><tr><td>&quot;You always mess up&quot;</td><td>&quot;Next shot, fresh start&quot;</td></tr><tr><td>&quot;Everyone&#39;s watching you fail&quot;</td><td>&quot;I&#39;ve done this before&quot;</td></tr><tr><td>&quot;You&#39;re not good enough&quot;</td><td>&quot;Trust the process&quot;</td></tr></tbody></table><p><strong>Reframe:</strong> Pause → Reframe → Reset → Refocus</p><hr><h2 id="_3-breath-reset" tabindex="-1">3-Breath Reset <a class="header-anchor" href="#_3-breath-reset" aria-label="Permalink to &quot;3-Breath Reset&quot;">​</a></h2><p><strong>Use after mistakes or pressure:</strong></p><ol><li><strong>Breath 1:</strong> Notice tension (where?)</li><li><strong>Breath 2:</strong> Release tension (let go)</li><li><strong>Breath 3:</strong> Refocus (this shot, now)</li></ol><hr><h2 id="pre-shot-routine" tabindex="-1">Pre-Shot Routine <a class="header-anchor" href="#pre-shot-routine" aria-label="Permalink to &quot;Pre-Shot Routine&quot;">​</a></h2><p><strong>Same routine, every shot:</strong></p><ol><li><strong>Visualize</strong> - See the shot</li><li><strong>Breathe</strong> - One deep breath</li><li><strong>Anchor</strong> - Touch boule, feel weight</li><li><strong>Execute</strong> - Trust and throw</li></ol><hr><h2 id="mistake-recovery-protocol" tabindex="-1">Mistake Recovery Protocol <a class="header-anchor" href="#mistake-recovery-protocol" aria-label="Permalink to &quot;Mistake Recovery Protocol&quot;">​</a></h2><p><strong>After a bad shot:</strong></p><ol><li><strong>Acknowledge</strong> - &quot;Didn&#39;t go as planned&quot;</li><li><strong>Release</strong> - Physical reset (shake it off)</li><li><strong>Refocus</strong> - &quot;Next shot is new&quot;</li><li><strong>Execute</strong> - Trust your routine</li></ol><hr><h2 id="this-week-s-practice" tabindex="-1">This Week&#39;s Practice <a class="header-anchor" href="#this-week-s-practice" aria-label="Permalink to &quot;This Week&#39;s Practice&quot;">​</a></h2><p><strong>Choose ONE technique:</strong></p><ul><li>[ ] 3-Breath Reset after every mistake</li><li>[ ] Pre-shot routine on every throw</li><li>[ ] Reframe one Inner Critic thought per session</li><li>[ ] Practice switching planning → execution mode</li></ul><hr><h2 id="track-your-progress" tabindex="-1">Track Your Progress <a class="header-anchor" href="#track-your-progress" aria-label="Permalink to &quot;Track Your Progress&quot;">​</a></h2><p><strong>Notice:</strong></p><ul><li>When do you feel most in flow?</li><li>What triggers your Inner Critic?</li><li>Which technique helps you most?</li><li>How does your performance change?</li></ul><hr><h2 id="key-principles" tabindex="-1">Key Principles <a class="header-anchor" href="#key-principles" aria-label="Permalink to &quot;Key Principles&quot;">​</a></h2><ol><li><strong>Flow is accessible</strong> - You can learn to enter it consistently</li><li><strong>Your inner voice matters</strong> - Coach yourself, don&#39;t criticize</li><li><strong>Simple tools work</strong> - 3 breaths, a routine, a reset</li><li><strong>Practice is key</strong> - Mental skills need training like technical skills</li></ol><hr><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><strong>Continue learning at carreau.app:</strong></p><ul><li>The Zone - Flow state deep dive</li><li>Mental Strength - Advanced pressure management</li><li>Goal Template - Structure your development</li><li>Diary Template - Track your progress</li></ul><hr><p><strong>Remember:</strong> Mental training is not about positive thinking.<br> It&#39;s about practical techniques that help you access your best performance under pressure.</p><hr><p><em>Pétanque Academy - Elite Player Development</em><br><em>carreau.app</em></p>',42)])])}]]);export{a as __pageData,n as default};
